// ========================================================================
// INDEXES + QUERY HELPERS
// ========================================================================

// Muscle group name → canonical MUSCLE_INFO key
var POOL_GROUP_TO_MUSCLE = {
  chest: "Pectoralis Major",
  back: "Latissimus Dorsi",         // most back exercises hit lats primary
  biceps: "Biceps Brachii",
  triceps: "Triceps Brachii",
  delts: "Lateral Deltoid",         // most delt work in the pool is lateral raises
  upper_traps_neck: "Trapezius",
  quads: "Quadriceps",
  hamstrings: "Hamstrings",
  glutes: "Glutes",
  calves: "Calves",
  abs: "Rectus Abdominis",
  forearms: "Forearms",
};

// Refine muscle assignment based on exercise name patterns within a group.
// This lets us route lateral raises → Lateral Deltoid, rear delt fly → Posterior Deltoid, etc.
function _refineMuscle(group, name) {
  var n = (name || "").toLowerCase();
  if (group === "delts") {
    if (/rear|reverse|face pull|posterior/.test(n)) return "Posterior Deltoid";
    if (/front raise|shoulder press|ohp|military|arnold|push press|overhead .*press|overhead press|standing.*press|seated.*press/.test(n)) return "Anterior Deltoid";
    if (/lateral|side/.test(n)) return "Lateral Deltoid";
    if (/shrug|upright row/.test(n)) return "Trapezius";
    return "Lateral Deltoid";
  }
  if (group === "back") {
    if (/deadlift|good morning|back extension|hyperextension|erector/.test(n)) return "Erector Spinae";
    if (/row/.test(n)) return "Rhomboids";
    if (/shrug/.test(n)) return "Trapezius";
    if (/pulldown|pull-up|pullup|pull up|chin/.test(n)) return "Latissimus Dorsi";
    return "Latissimus Dorsi";
  }
  if (group === "upper_traps_neck") {
    if (/neck|harness/.test(n)) return "Neck (Cervical)";
    return "Trapezius";
  }
  if (group === "chest" && /dip/.test(n)) return "Pectoralis Major";
  if (group === "quads") {
    if (/tibialis|shin/.test(n)) return "Tibialis Anterior";
    if (/adductor|copenhagen|cossack/.test(n)) return "Adductors";
    return "Quadriceps";
  }
  return POOL_GROUP_TO_MUSCLE[group] || "Full Body";
}

// Movement pattern inference from exercise name
function _inferPattern(name) {
  var n = (name || "").toLowerCase();
  if (/deadlift/.test(n)) return "Hip Hinge";
  if (/rdl|romanian|good morning/.test(n)) return "Hip Hinge";
  if (/squat|leg press|lunge|split squat|step-up|stepup/.test(n)) return "Squat";
  if (/hip thrust|glute bridge|kickback/.test(n)) return "Hip Extension";
  if (/bench press|dumbbell press|db press|dip|push[- ]?up|push press|incline press|decline press|flye|fly/.test(n)) return "Horizontal Push";
  if (/shoulder press|ohp|military|overhead press|arnold/.test(n)) return "Vertical Push";
  if (/pull-up|pullup|pull up|chin|pulldown/.test(n)) return "Vertical Pull";
  if (/row|face pull/.test(n)) return "Horizontal Pull";
  if (/curl/.test(n) && !/leg curl|hamstring curl|wrist/.test(n)) return "Elbow Flexion";
  if (/pushdown|tricep|kickback|skull|jm press/.test(n)) return "Elbow Extension";
  if (/leg curl|hamstring curl|nordic/.test(n)) return "Knee Flexion";
  if (/leg extension|knee extension/.test(n)) return "Knee Extension";
  if (/calf/.test(n)) return "Calf Raise";
  if (/crunch|sit-up|situp|leg raise|ab wheel|plank|hanging/.test(n)) return "Spinal Flexion";
  if (/carry|walk|farmer|sled|prowler/.test(n)) return "Loaded Carry";
  if (/lateral raise|side raise/.test(n)) return "Isolation";
  if (/rear delt|reverse fly/.test(n)) return "Isolation";
  return "Compound";
}

// Compound flag inference
function _inferCompound(name) {
  var n = (name || "").toLowerCase();
  var compounds = /squat|deadlift|bench press|row|pulldown|pull-?up|chin|dip|shoulder press|ohp|military|arnold|clean|snatch|thrust|leg press|lunge|split squat|carry|swing|thruster|block pull|rack pull|good morning|hip thrust|bulgarian|front squat|zercher|hack squat|belt squat|goblet squat|overhead press/;
  return compounds.test(n);
}

// Location inference from equipment
function _inferLocation(equipment) {
  var e = (equipment || "").toLowerCase();
  if (/smith|cable|t-bar|hack|machine/.test(e)) return "gym_required";
  if (/barbell/.test(e)) return "gym_or_home_gym";
  if (/dumbbell|db/.test(e)) return "gym_or_home_gym";
  if (/bodyweight|band|plate/.test(e)) return "home_ok";
  return "gym_or_home_gym";
}

// Flat exercise list: one entry per unique name, primary muscle assigned
var EXERCISE_POOL_FLAT = [];
var EXERCISE_POOL_BY_NAME = {};       // name → entry (also indexes aliases)
var EXERCISE_POOL_BY_MUSCLE = {};     // muscle → [entries]
var EXERCISE_POOL_BY_GROUP = {};      // pool group key → [entries]

(function _buildPoolIndexes() {
  if (typeof EXERCISE_POOL_RAW === "undefined") return;
  var groups = EXERCISE_POOL_RAW.muscle_groups || {};
  Object.keys(groups).forEach(function(group) {
    (groups[group] || []).forEach(function(raw) {
      var muscle = _refineMuscle(group, raw.name);
      var pattern = _inferPattern(raw.name);
      var compound = _inferCompound(raw.name);
      var location = _inferLocation(raw.equipment);
      var entry = {
        name: raw.name,
        aliases: raw.aliases || [],
        equipment: raw.equipment || "",
        muscle: muscle,
        pool_group: group,
        pattern: pattern,
        compound: compound,
        location: location,
        prescriptions: raw.prescriptions || [],
        notes: raw.notes || "",
        technique_cues: raw.technique_cues || [],
        _source_ref: (raw.prescriptions || []).map(function(p) { return p.source_ref; }).filter(Boolean),
      };
      EXERCISE_POOL_FLAT.push(entry);
      EXERCISE_POOL_BY_NAME[raw.name] = entry;
      (raw.aliases || []).forEach(function(al) { EXERCISE_POOL_BY_NAME[al] = entry; });
      if (!EXERCISE_POOL_BY_MUSCLE[muscle]) EXERCISE_POOL_BY_MUSCLE[muscle] = [];
      EXERCISE_POOL_BY_MUSCLE[muscle].push(entry);
      if (!EXERCISE_POOL_BY_GROUP[group]) EXERCISE_POOL_BY_GROUP[group] = [];
      EXERCISE_POOL_BY_GROUP[group].push(entry);
    });
  });
})();

// ---- QUERY API ----
function poolExercisesForMuscle(muscle) {
  return (EXERCISE_POOL_BY_MUSCLE[muscle] || []).slice();
}

function poolLookup(name) {
  if (!name) return null;
  return EXERCISE_POOL_BY_NAME[name] || null;
}

// Best-effort prescription for an exercise given the user's goal.
// Preference order for context matching:
//   goal="strength"   → powerbuilding_primary → powerbuilding_secondary → hypertrophy_bodypart
//   goal="hypertrophy"→ hypertrophy_bodypart → powerbuilding_isolation → powerbuilding_secondary
//   goal="women"      → women_program → hypertrophy_bodypart
//   default            → hypertrophy_bodypart → powerbuilding_secondary
function poolPrescription(name, goal) {
  var entry = poolLookup(name);
  if (!entry || !entry.prescriptions.length) return null;
  var priority;
  if (goal === "strength") priority = ["powerbuilding_primary","powerbuilding_secondary","hypertrophy_bodypart"];
  else if (goal === "women") priority = ["women_program","hypertrophy_bodypart","powerbuilding_secondary"];
  else priority = ["hypertrophy_bodypart","powerbuilding_isolation","powerbuilding_secondary","powerbuilding_primary","women_program"];
  for (var i = 0; i < priority.length; i++) {
    var found = entry.prescriptions.find(function(p) { return p.context === priority[i]; });
    if (found) return found;
  }
  return entry.prescriptions[0];
}

// ---- MOBILITY ROUTINES ----
// Returns the routine for a given region and week. Regions: hip, shoulder, posture, hamstring
function poolMobilityRoutine(region, week) {
  var guides = EXERCISE_POOL_RAW.mobility_guides || {};
  var regionKey = ({
    hip: "hip_mobility", hips: "hip_mobility",
    shoulder: "shoulder_mobility", shoulders: "shoulder_mobility",
    posture: "posture_spinal_mobility", thoracic: "posture_spinal_mobility",
    hamstring: "hamstring_mobility", hamstrings: "hamstring_mobility",
  })[region] || null;
  if (!regionKey) return null;
  var guide = guides[regionKey];
  if (!guide) return null;
  // Try week-specific first (week_1_moves, week_1_2_moves, week_3_4_moves, etc.)
  var weekNames = ["week_" + week + "_moves", "week_1_2_moves", "week_3_4_moves", "week_1_moves"];
  for (var i = 0; i < weekNames.length; i++) {
    if (guide[weekNames[i]]) return { region: regionKey, moves: guide[weekNames[i]] };
  }
  // Fallback: first list-valued key
  for (var k in guide) {
    if (Array.isArray(guide[k])) return { region: regionKey, moves: guide[k] };
  }
  return null;
}

// ---- SUBSTITUTIONS ----
// Returns array of substitute names for a given exercise from the FBHF sub table.
function poolSubstitutionsFor(name) {
  var fbhf = EXERCISE_POOL_RAW.full_body_high_frequency_program || {};
  var subs = fbhf.exercise_substitutions_full_list || {};
  // Try direct key: normalize name → SCREAMING_SNAKE
  var key = String(name || "").toUpperCase().replace(/[^A-Z0-9]+/g, "_").replace(/^_|_$/g, "");
  if (subs[key]) return subs[key].slice();
  // Try loose match by scanning keys
  var norm = String(name || "").toLowerCase().replace(/[^a-z0-9]+/g, "");
  for (var k in subs) {
    var kn = k.toLowerCase().replace(/[^a-z0-9]+/g, "");
    if (kn === norm) return subs[k].slice();
  }
  return [];
}

// ---- MOBILITY REGIONS (for intake) ----
function poolMobilityRegions() {
  return ["hip","shoulder","posture","hamstring"];
}

// ---- WOMEN'S SPECIALIZATION PROGRAM (fixed 4-week × 3-day) ----
function poolWomensSpecializationProgram() {
  var w = EXERCISE_POOL_RAW.womens_specialization_program;
  if (!w) return null;
  return w;
}
